arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H "Content-Type: application/json" -d '{"token":"***","channel":"C_INC","limit":999}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit()
for m in d.get('messages',[]):
    t=m.get('text','')
    if 'freeze' in t.lower() or 'deploy' in t.lower():
        print(m['ts'], '|', m['user'], '| replies:', m.get('reply_count','n/a'), '|', t[:120].replace(chr(10),' / '))
"

